insert into public.recipe_steps (family_id, recipe_id, created_by, updated_by, source, id, position, name, body, timer_seconds, timer_label, temp_check_c, temp_check_text, tip) values
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000001', 0, 'Rinse the sushi rice', 'Put {ing:c0c01000-0000-4000-8000-000300000001} in a fine-mesh strainer. Rinse under cold water until the water runs almost clear, then drain well.', null, null, null, null, 'Rinsing off the extra starch keeps the rice from turning gummy while it stays sticky.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000002', 1, 'Cook the rice', 'Put the rinsed rice in a saucepan with {ing:c0c01000-0000-4000-8000-000300000002}. Bring to a boil, cover, turn the heat to low and cook without lifting the lid.', 900, 'Cook sushi rice', null, null, 'Keep the lid on to hold in the steam. With a rice cooker, use its sushi rice setting and water ratio.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000003', 2, 'Rest the rice', 'Take the pan off the heat and let the rice rest, covered.', 600, 'Rest rice', null, null, null),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000004', 3, 'Season the sushi rice', 'Stir {ing:c0c01000-0000-4000-8000-000300000003}, {ing:c0c01000-0000-4000-8000-000300000004} and {ing:c0c01000-0000-4000-8000-000300000005} together until dissolved. Spread the rice in a wide bowl and gently fold in the seasoning. Let it cool until lukewarm.', null, null, null, null, 'Cut and fold rather than stir, so the grains don''t break.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000005', 4, 'Make the tuna marinade', 'In a bowl, whisk {ing:c0c01000-0000-4000-8000-000300000007}, {ing:c0c01000-0000-4000-8000-000300000008}, {ing:c0c01000-0000-4000-8000-000300000009}, {ing:c0c01000-0000-4000-8000-000300000010}, {ing:c0c01000-0000-4000-8000-000300000011} and {ing:c0c01000-0000-4000-8000-000300000012} until the honey dissolves.', null, null, null, null, 'Taste it before adding the tuna: it should be savory, a little sweet and tangy.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000006', 5, 'Marinate the fish', 'Cut {ing:c0c01000-0000-4000-8000-000300000006} into even 1.5–2 cm cubes. Toss gently with the marinade, cover and refrigerate.', 600, 'Marinate fish', null, null, 'Use fish sold for eating raw and keep it cold until serving. Don''t marinate longer: the acid changes the texture.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000007', 6, 'Prepare the toppings', 'Dice {ing:c0c01000-0000-4000-8000-000300000013}, {ing:c0c01000-0000-4000-8000-000300000014} and {ing:c0c01000-0000-4000-8000-000300000017}. Cut {ing:c0c01000-0000-4000-8000-000300000015} into small cubes. Cook {ing:c0c01000-0000-4000-8000-000300000016} as the package says, then cool. Finely slice {ing:c0c01000-0000-4000-8000-000300000018}.', null, null, null, null, 'Cut the cream cheese straight from the fridge for clean cubes. Keep the avocado in fairly large pieces so it doesn''t turn mushy.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000008', 7, 'Make the spicy mayo', 'Whisk {ing:c0c01000-0000-4000-8000-000300000019}, {ing:c0c01000-0000-4000-8000-000300000020}, {ing:c0c01000-0000-4000-8000-000300000021} and {ing:c0c01000-0000-4000-8000-000300000022} until smooth. Add a teaspoon of water if it''s too thick to drizzle.', null, null, null, null, 'Start with half the sriracha for a milder sauce, then add more to taste.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000009', 8, 'Assemble the bowls', 'Divide the rice among 4 bowls. Arrange the fish, avocado, cucumber, cream cheese, edamame and mango in separate sections on top.', null, null, null, null, 'Use lukewarm rice, never hot rice right against raw fish. Assemble just before serving.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000003', 'c0c0a000-0000-4000-8000-00000000000c', 'c0c0a000-0000-4000-8000-00000000000c', 'app', 'c0c02000-0000-4000-8000-000300000010', 9, 'Finish and serve', 'Drizzle the spicy mayo over each bowl. Sprinkle with {ing:c0c01000-0000-4000-8000-000300000023}, {ing:c0c01000-0000-4000-8000-000300000024} and the scallions. Serve right away.', null, null, null, null, 'Add the crispy onions at the very last moment so they stay crunchy.');
