insert into public.recipe_steps (family_id, recipe_id, created_by, updated_by, source, id, position, name, body, timer_seconds, timer_label, temp_check_c, temp_check_text, tip) values
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000001', 0, 'Preheat the oven', 'Preheat the oven to {temp:190}. Get out a baking dish about 20 × 20 cm (8 × 8 in).', null, null, null, null, 'A fairly shallow dish gives an even layer of apples under a thick, crisp topping.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000002', 1, 'Prepare the apples', 'Peel and core {ing:c0c01000-0000-4000-8000-000400000001}, then cut into chunks of about 2 cm. Toss with {ing:c0c01000-0000-4000-8000-000400000003}, {ing:c0c01000-0000-4000-8000-000400000004} and {ing:c0c01000-0000-4000-8000-000400000005}.', null, null, null, null, 'Mixing tart Granny Smith with sweeter Honeycrisp or Pink Lady balances the flavor and texture.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000003', 2, 'Pre-cook the apples', 'Melt {ing:c0c01000-0000-4000-8000-000400000002} in a large pan over medium heat. Add the apples and cook, stirring now and then, until slightly soft but still holding their shape. Tip them into the baking dish.', 360, 'Pre-cook apples', null, null, 'Don''t cook them through: they keep softening in the oven.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000004', 3, 'Make the crumble topping', 'Mix {ing:c0c01000-0000-4000-8000-000400000006}, {ing:c0c01000-0000-4000-8000-000400000008} and {ing:c0c01000-0000-4000-8000-000400000009} in a bowl. Add {ing:c0c01000-0000-4000-8000-000400000007} and rub together with your fingertips until it looks like coarse breadcrumbs with some bigger chunks.', null, null, null, null, 'Keep the butter cold and leave some pieces about 1 cm across. Don''t overwork it: bigger chunks bake crisper.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000005', 4, 'Assemble', 'Scatter the crumble evenly over the apples in a thick, generous layer. Don''t press it down.', null, null, null, null, 'A loose topping lets the hot air through, so it turns golden and crunchy.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000006', 5, 'Bake until golden', 'Bake at {temp:190} until the topping is deep golden and crisp and the juices bubble at the edges.', 2100, 'Bake crumble', 90, 'The apples should be tender when pierced with a knife.', 'Check after 30 minutes. If the top browns before the apples are tender, cover it loosely with foil.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000400000007', 6, 'Rest and serve', 'Let the crumble rest before serving warm, with vanilla ice cream or crème fraîche if you like.', 600, 'Rest crumble', null, null, 'Resting lets the juices thicken a little, so it holds together when served.');
insert into public.recipe_variants (family_id, recipe_id, created_by, updated_by, source, id, position, name, kind, changes) values
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c03000-0000-4000-8000-000400000001', 0, 'Almond crumble', 'version'::public.variant_kind, '[{"type":"swap_ingredient","ingredient_id":"c0c01000-0000-4000-8000-000400000006","with":[{"id":"c0c01000-0000-4000-8000-000400000006","name":"All-purpose flour","quantity":120,"unit":"g","catalog_key":"all_purpose_flour"},{"id":"c0c04000-0000-4000-8000-000400000001","name":"Ground almonds","quantity":30,"unit":"g","catalog_key":"almonds"}]},{"type":"change_step","step_id":"c0c02000-0000-4000-8000-000400000004","body":"Mix {ing:c0c01000-0000-4000-8000-000400000006}, {ing:c0c04000-0000-4000-8000-000400000001}, {ing:c0c01000-0000-4000-8000-000400000008} and {ing:c0c01000-0000-4000-8000-000400000009} in a bowl. Add {ing:c0c01000-0000-4000-8000-000400000007} and rub together with your fingertips until it looks like coarse breadcrumbs with some bigger chunks."}]'),
