  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000004', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c03000-0000-4000-8000-000400000003', 2, 'Extra crispy topping', 'option'::public.variant_kind, '[{"type":"add_step","step_id":"c0c02000-0000-4000-8000-000400000005","place":"before","step":{"name":"Chill the crumble","body":"Refrigerate the crumble topping before scattering it over the apples.","timer_seconds":1200,"timer_label":"Chill crumble","tip":"Cold butter keeps the irregular chunks, which bake into a crisp, crunchy crust."}}]');

