insert into public.recipe_steps (family_id, recipe_id, created_by, updated_by, source, id, position, name, body, timer_seconds, timer_label, temp_check_c, temp_check_text, tip) values
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000001', 0, 'Preheat the oven', 'Preheat the oven to {temp:175} (conventional bake). Grease a 23 × 13 cm (9 × 5 in) loaf pan and line it with parchment paper.', null, null, null, null, 'Leave some parchment hanging over the sides to lift the loaf out easily.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000002', 1, 'Mash the bananas', 'Peel {ing:c0c01000-0000-4000-8000-000500000001} and mash with a fork in a large bowl. Leave a few small chunks for texture.', null, null, null, null, 'Heavily spotted or nearly black bananas are sweeter, softer and more flavorful.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000003', 2, 'Mix the wet ingredients', 'In another bowl, mix {ing:c0c01000-0000-4000-8000-000500000003} with {ing:c0c01000-0000-4000-8000-000500000004}. Whisk in {ing:c0c01000-0000-4000-8000-000500000005} and {ing:c0c01000-0000-4000-8000-000500000007}, then stir in the mashed bananas.', null, null, null, null, 'Let the butter cool a little before adding the eggs so they don''t start to cook.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000004', 3, 'Combine the dry ingredients', 'In a third bowl, whisk {ing:c0c01000-0000-4000-8000-000500000002}, {ing:c0c01000-0000-4000-8000-000500000006} and {ing:c0c01000-0000-4000-8000-000500000008} together.', null, null, null, null, 'Mixing them first spreads the baking soda evenly through the batter.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000005', 4, 'Make the batter', 'Add the dry ingredients to the wet ones. Fold gently with a spatula until no dry flour remains. The batter should be thick and a little lumpy.', null, null, null, null, 'Don''t overmix, or the bread turns dense and rubbery. Stop as soon as the flour disappears.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000006', 5, 'Fill the loaf pan', 'Pour the batter into the pan and smooth the top with a spatula.', null, null, null, null, null),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000007', 6, 'Bake', 'Bake at {temp:175} on the middle rack until the top is golden brown and a toothpick in the center comes out clean or with a few moist crumbs.', 3300, 'Bake (check at 55 min)', 94, 'Baking usually takes 55–65 minutes.', 'If the top browns too fast, cover it loosely with foil after about 40 minutes. Don''t open the oven too early.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000008', 7, 'Cool in the pan', 'Take the bread out of the oven and leave it in the pan to cool and firm up.', 900, 'Cool in pan', null, null, 'It''s fragile while hot and may break if you take it out now.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000005', 'c0c0a000-0000-4000-8000-00000000000b', 'c0c0a000-0000-4000-8000-00000000000b', 'chatgpt', 'c0c02000-0000-4000-8000-000500000009', 8, 'Cool and serve', 'Lift the bread out with the parchment and put it on a wire rack. Let it cool before cutting 8–10 slices.', 1800, 'Cool on rack', null, null, 'Best of all: toast a thick slice in a pan with a little butter until the edges caramelize.');
