insert into public.recipe_steps (family_id, recipe_id, created_by, updated_by, source, id, position, name, body, timer_seconds, timer_label, temp_check_c, temp_check_text, tip) values
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000006', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000600000001', 0, 'Melt the butter', 'Gently melt {ing:c0c01000-0000-4000-8000-000600000004} in a small saucepan over low heat. Keep it warm without boiling, and skim off any foam.', null, null, null, null, 'The butter should be melted and warm, not bubbling hard.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000006', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000600000002', 1, 'Make the hollandaise', 'In a heatproof bowl set over barely simmering water (not touching it), whisk {ing:c0c01000-0000-4000-8000-000600000005}, {ing:c0c01000-0000-4000-8000-000600000006} and {ing:c0c01000-0000-4000-8000-000600000007} until slightly thick. Slowly drizzle in the warm butter, whisking all the time. Season with some of the {ing:c0c01000-0000-4000-8000-000600000008} and {ing:c0c01000-0000-4000-8000-000600000009}.', null, null, null, null, 'Too thick? Whisk in a little warm water. Hollandaise uses undercooked yolks; pasteurized eggs lower the risk.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000006', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000600000003', 2, 'Toast the muffins and sear the bacon', 'Split {ing:c0c01000-0000-4000-8000-000600000002} and toast all the halves until golden. Sear {ing:c0c01000-0000-4000-8000-000600000003} in a skillet over medium heat, 1–2 minutes per side. Set aside.', 300, 'Toast and sear', null, null, null),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000006', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000600000004', 3, 'Poach the eggs in batches', 'Bring a wide saucepan of water to a gentle simmer and add {ing:c0c01000-0000-4000-8000-000600000010}. Crack {ing:c0c01000-0000-4000-8000-000600000001} into separate small bowls. Slide in 3–4 eggs at a time and poach until the whites are set and the yolks still runny. Lift them out with a slotted spoon.', 240, 'Poach eggs', 85, 'Keep the water just below a simmer, never at a rolling boil.', 'Fresh eggs hold their shape better.'),
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000006', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c02000-0000-4000-8000-000600000005', 4, 'Assemble and serve', 'Put a slice of bacon on each muffin half, top with a drained poached egg and spoon over the hollandaise. Finish with {ing:c0c01000-0000-4000-8000-000600000011} and a little more cayenne if you like. Serve right away.', null, null, null, null, 'Warm the plates first so the eggs stay hot longer.');
insert into public.recipe_variants (family_id, recipe_id, created_by, updated_by, source, id, position, name, kind, changes) values
  ('c0c0f000-0000-4000-8000-000000000001', 'c0c0e000-0000-4000-8000-000000000006', 'c0c0a000-0000-4000-8000-00000000000a', 'c0c0a000-0000-4000-8000-00000000000a', 'app', 'c0c03000-0000-4000-8000-000600000001', 0, 'Make ahead', 'option'::public.variant_kind, '[{"type":"add_step","step_id":"c0c02000-0000-4000-8000-000600000004","place":"after","step":{"name":"Chill and reheat the eggs","body":"Move the poached eggs to ice-cold water, and refrigerate them if you''re cooking ahead. Just before assembling, reheat them in hot water for 45–60 seconds.","temp_check_c":72,"temp_check_text":"Reheat in water just off the simmer, not boiling."}}]');

